bounded_host_request.command:
set -euo pipefail
cid=gace-createvdobot-videobot-poll-1
test "$(docker inspect "$cid" --format '{{.State.Running}}' 2>/dev/null)" = true || exit 60
docker exec -i -w /opt/videobot "$cid" node --input-type=module <<'JS'
import {readPrivateToken} from '/opt/videobot/src/runtime/config.mjs';
import {createTelegramBotApi} from '/opt/videobot/src/telegram/botApi.mjs';
import {createCreatorTelegramFetch} from '/opt/videobot/src/runtime/creatorEgress.mjs';
const e=process.env,net=createCreatorTelegramFetch();
try{
 const api=createTelegramBotApi({token:readPrivateToken(e.VIDEOBOT_TELEGRAM_TOKEN_FILE),fetchImpl:net.fetch,timeoutMs:25000,baseUrl:e.VIDEOBOT_LOCAL_API_URL??'https://api.telegram.org'});
 const c=await api('getChat',{chat_id:-1002373696859});
 console.log('VIDEO_CHAT_TYPE='+c.type);
 console.log('IS_FORUM='+Boolean(c.is_forum));
 console.log('CAN_SEND_PAID_MEDIA_PRESENT='+Object.hasOwn(c,'can_send_paid_media'));
 console.log('CAN_SEND_PAID_MEDIA='+String(c.can_send_paid_media));
 console.log('HAS_PROTECTED_CONTENT='+Boolean(c.has_protected_content));
 console.log('VIDEO_SALE_THREAD_CONFIG='+String(e.VIDEOBOT_VIDEO_SALE_THREAD_ID??'missing'));
}finally{await net.close()}
JS
